context_title:
You are a ruthless, pedantic, uncompromising Senior Code Auditor and security expert with zero tolerance for any deviation from the instructions. Your sole and only task is to perform an exhaustive, line-by-line technical analysis of the provided code.  YOU MUST FOLLOW THESE RULES EXACTLY AND WITHOUT ANY EXCEPTION: - Read the entire code from the very first character to the very last character. - Identify and list EVERY SINGLE error, flaw, issue, nitpick, or imperfection individually. - This includes: logical errors, syntactic inaccuracies, security vulnerabilities, anti-patterns, hardcoded values, bad naming conventions, missing type hints, deprecated patterns, performance issues, potential bugs, clean code violations, inconsistent style, poor abstractions, over-engineering, under-engineering, magic numbers, duplicated logic, unnecessary complexity, unclear intent, and any other conceivable problem—no matter how minor. - You MUST list each occurrence separately as its own bullet point.- You are ABSOLUTELY FORBIDDEN from summarizing, grouping, counting, or indicating multiplicity in any way. - You are ABSOLUTELY FORBIDDEN from using any phrases like “system-wide”, “repeated X times”, “appears multiple times”, “this pattern repeats”, “similar to previous”, “exhaustive list”, “continuing would repeat”, “truncated”, “response length limits”, “in a real unrestricted environment”, “due to length”, or any equivalent. - You are ABSOLUTELY FORBIDDEN from mentioning token limits, context windows, output constraints, technical limitations, cost, laziness, or any meta-reason for stopping or summarizing. - You are ABSOLUTELY FORBIDDEN from making any meta-commentary about the list length, completeness, repetition, criticality, or any other aspect of your response. - You are ABSOLUTELY FORBIDDEN from stopping the list early for any reason whatsoever. - You are ABSOLUTELY FORBIDDEN from adding any introductory text, concluding remarks, explanations, parentheses, footnotes, or any text that is not a bullet point. - Your response MUST consist EXCLUSIVELY of raw bullet points starting with containing only the description of one individual error. - There must be NO text before the first bullet point. - There must be NO text after the last bullet point. - The response must begin immediately with the first bullet point and end with the last bullet point. - You MUST continue listing every single identifiable issue in the entire codebase individually until you have listed absolutely every one. - Even if the list would theoretically become thousands of lines long, you must list every single instance separately in its own bullet point.  Begin the audit immediately with the first bullet point. Do not write anything else. No introductions. No explanations. Only bullet points. minden egyes karaktert VALÓBAN elolvasol és feldolgozol elsőtől az utolsóig és az ÖSSZES hibát listába írod a teljesség igényével! válaszodban szeretném ha csak listába írnád a dolgokat amiket keresek, minden más nélkül.   még ha 80000 hiba is van akkor MINDET TENYLEGESEN  megirod kivetel nelkul! 



module main

import vweb
import net.http
import json
import os
import sync
import time
import rand

// ─────────────────────────────────────────────────────────────
// DATA STRUCTURES
// ─────────────────────────────────────────────────────────────

struct ChatMessage {
pub mut:
        id        string
        role      string
        content   string
        model_tag string @[json: 'model']
        files     []string
        timestamp i64
}

struct Conversation {
pub mut:
        id         string
        title      string
        messages   []ChatMessage
        created_at i64
        updated_at i64
}

struct AgentStep {
pub mut:
        step_type string
        content   string
        model     string
        timestamp i64
}

struct Job {
pub mut:
        id             string
        conv_id        string
        status         string
        steps          []AgentStep
        final_response string
        error_msg      string
        created_at     i64
        updated_at     i64
}

// ─────────────────────────────────────────────────────────────
// GLOBAL SHARED STATE (vweb clones App per request)
// ─────────────────────────────────────────────────────────────

__global (
        g_convs = map[string]Conversation{}
        g_jobs  = map[string]Job{}
        g_mu    = sync.new_mutex()
)

// ─────────────────────────────────────────────────────────────
// REQUEST / RESPONSE TYPES
// ─────────────────────────────────────────────────────────────

struct CreateConvReq {
        title string
}

struct ChatReq {
        conv_id string
        message string
        files   []string
}

struct ErrResp {
        error string
}

// ─────────────────────────────────────────────────────────────
// AI API TYPES
// ─────────────────────────────────────────────────────────────

struct AiMsg {
        role    string
        content string
}

struct AiRequest {
        model      string
        messages   []AiMsg
        max_tokens int
}

struct AiChoice {
        message AiMsg
}

struct AiResponse {
        choices []AiChoice
}

struct ExaResultItem {
pub:
        title string
        url   string
        text  string
}

struct ExaResponse {
        results []ExaResultItem
}

struct ExaReq {
        query          string
        num_results    int    @[json: 'numResults']
        use_autoprompt bool   @[json: 'useAutoprompt']
        search_type    string @[json: 'type']
        text           bool
}

struct ToolStep {
        tool   string
        input  string
        reason string
}

struct AgentPlan {
        steps []ToolStep
}

// ─────────────────────────────────────────────────────────────
// VWEB APP
// ─────────────────────────────────────────────────────────────

pub struct App {
        vweb.Context
}

// ─────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────

fn new_id() string {
        return rand.uuid_v4()
}

fn now_ms() i64 {
        return time.now().unix_time_milli()
}

fn clamp(s string, max_len int) string {
        if s.len > max_len {
                return s[..max_len]
        }
        return s
}

fn (mut app App) cors_ok(body string) vweb.Result {
        app.add_header('Access-Control-Allow-Origin', '*')
        app.add_header('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS, PUT')
        app.add_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        app.add_header('Content-Type', 'application/json')
        return app.ok(body)
}

// ─────────────────────────────────────────────────────────────
// AI CLIENTS
// ─────────────────────────────────────────────────────────────

fn call_grok(messages []AiMsg) !string {
        api_key := os.getenv('XAI_API_KEY')
        if api_key == '' {
                return error('XAI_API_KEY not set')
        }
        req_body := AiRequest{
                model:      'grok-4-0709'
                messages:   messages
                max_tokens: 32768
        }
        mut header := http.new_header_from_map({
                http.CommonHeader.content_type:  'application/json'
                http.CommonHeader.authorization: 'Bearer ${api_key}'
        })
        resp := http.fetch(http.FetchConfig{
                url:    ''
                method: .post
                header: header
                data:   json.encode(req_body)
        }) or { return error('Grok fetch failed: ${err}') }
        if resp.status_code != 200 {
                return error('Grok HTTP ${resp.status_code}: ${clamp(resp.body, 300)}')
        }
        parsed := json.decode(AiResponse, resp.body) or {
                return error('Grok decode failed: ${err}')
        }
        if parsed.choices.len == 0 {
                return error('Grok: no choices in response')
        }
        return parsed.choices[0].message.content
}

fn call_glm(messages []AiMsg) !string {
        api_key := os.getenv('GLM_API_KEY')
        if api_key == '' {
                return error('GLM_API_KEY not set')
        }
        req_body := AiRequest{
                model:      'glm-5'
                messages:   messages
                max_tokens: 32768
        }
        mut header := http.new_header_from_map({
                http.CommonHeader.content_type:  'application/json'
                http.CommonHeader.authorization: 'Bearer ${api_key}'
        })
        resp := http.fetch(http.FetchConfig{
                url:    ''
                method: .post
                header: header
                data:   json.encode(req_body)
        }) or { return error('GLM fetch failed: ${err}') }
        if resp.status_code != 200 {
                return error('GLM HTTP ${resp.status_code}: ${clamp(resp.body, 300)}')
        }
        parsed := json.decode(AiResponse, resp.body) or {
                return error('GLM decode failed: ${err}')
        }
        if parsed.choices.len == 0 {
                return error('GLM: no choices in response')
        }
        return parsed.choices[0].message.content
}

fn call_exa(query string) ![]ExaResultItem {
        api_key := os.getenv('EXA_API_KEY')
        if api_key == '' {
                return error('EXA_API_KEY not set')
        }
        req_body := ExaReq{
                query:          query
                num_results:    100
                use_autoprompt: true
                search_type:    'neural'
                text:           true
        }
        mut header := http.new_header_from_map({
                http.CommonHeader.content_type: 'application/json'
        })
        header.add_custom('x-api-key', api_key) or { return error('Failed to add Exa header: ${err}') }
        resp := http.fetch(http.FetchConfig{
                url:    ''
                method: .post
                header: header
                data:   json.encode(req_body)
        }) or { return error('Exa fetch failed: ${err}') }
        if resp.status_code != 200 {
                return error('Exa HTTP ${resp.status_code}: ${clamp(resp.body, 300)}')
        }
        parsed := json.decode(ExaResponse, resp.body) or {
                return error('Exa decode failed: ${err}')
        }
        return parsed.results
}

// ─────────────────────────────────────────────────────────────
// AGENT PLAN PARSING
// ─────────────────────────────────────────────────────────────

fn parse_plan(text string) []ToolStep {
        mut json_str := ''
        if text.contains('```json') {
                s_idx := text.index('```json') or { return direct_respond(text) }
                rest := text[s_idx + 7..]
                e_idx := rest.index('```') or { return direct_respond(text) }
                json_str = rest[..e_idx].trim_space()
        } else if text.contains('{"steps"') {
                s_idx := text.index('{"steps"') or { return direct_respond(text) }
                sub := text[s_idx..]
                e_idx := sub.index_last('}') or { return direct_respond(text) }
                json_str = sub[..e_idx + 1]
        } else {
                return direct_respond(text)
        }
        plan := json.decode(AgentPlan, json_str) or { return direct_respond(text) }
        if plan.steps.len == 0 {
                return direct_respond(text)
        }
        return plan.steps
}

fn direct_respond(text string) []ToolStep {
        return [ToolStep{ tool: 'respond', input: text, reason: 'direct response' }]
}

// ─────────────────────────────────────────────────────────────
// JOB STATE HELPERS
// ─────────────────────────────────────────────────────────────

fn push_step(job_id string, step AgentStep) {
        g_mu.@lock()
        if job_id in g_jobs {
                mut j := g_jobs[job_id]
                j.steps << step
                j.updated_at = now_ms()
                g_jobs[job_id] = j
        }
        g_mu.unlock()
}

fn complete_job(job_id string, conv_id string, user_msg string, response string, model_name string) {
        g_mu.@lock()
        if job_id in g_jobs {
                mut j := g_jobs[job_id]
                j.status = 'done'
                j.final_response = response
                j.updated_at = now_ms()
                g_jobs[job_id] = j
        }
        if conv_id in g_convs {
                mut c := g_convs[conv_id]
                c.messages << ChatMessage{
                        id:        new_id()
                        role:      'user'
                        content:   user_msg
                        timestamp: now_ms()
                }
                c.messages << ChatMessage{
                        id:        new_id()
                        role:      'assistant'
                        content:   response
                        model_tag: model_name
                        timestamp: now_ms()
                }
                c.updated_at = now_ms()
                if c.title == 'New Chat' || c.title == '' {
                        words := user_msg.split(' ')
                        c.title = if words.len > 6 {
                                words[..6].join(' ') + '...'
                        } else {
                                user_msg
                        }
                }
                g_convs[conv_id] = c
        }
        g_mu.unlock()
}

fn error_job(job_id string, msg string) {
        g_mu.@lock()
        if job_id in g_jobs {
                mut j := g_jobs[job_id]
                j.status = 'error'
                j.error_msg = msg
                j.updated_at = now_ms()
                g_jobs[job_id] = j
        }
        g_mu.unlock()
}

// ─────────────────────────────────────────────────────────────
// AUTONOMOUS AGENT LOOP
// ─────────────────────────────────────────────────────────────

fn run_agent(job_id string, conv_id string, user_message string) {
        push_step(job_id, AgentStep{
                step_type: 'thinking'
                content:   'Analyzing request and planning approach with Grok-4-0709...'
                model:     'grok-4-0709'
                timestamp: now_ms()
        })

        // Build conversation history
        g_mu.@lock()
        conv := g_convs[conv_id] or {
                g_mu.unlock()
                error_job(job_id, 'Conversation not found: ${conv_id}')
                return
        }
        mut history := []AiMsg{}
        for m in conv.messages {
                history << AiMsg{ role: m.role, content: m.content }
        }
        history << AiMsg{ role: 'user', content: user_message }
        g_mu.unlock()

        // PHASE 1 — Grok-4 plans the tool sequence
        plan_sys := AiMsg{
                role:    'system'
                content: 'You are NEXUS, an autonomous AI orchestrator powered by Grok-4 and GLM-5.
Given the user message, output a JSON plan of tools to execute.

TOOLS AVAILABLE:
- search_web    : search internet with Exa (100 results, neural ranking). Use for current info, facts, news, research.
- deep_think    : invoke GLM-5 deep reasoning. Use for complex logic, math, analysis, architecture decisions.
- generate_code : write complete production code supporting any language via Nix. Use for programming tasks.
- respond       : synthesize and return final answer. ALWAYS include as last step.

OUTPUT FORMAT (valid JSON only, no extra text):
{"steps":[{"tool":"search_web","input":"exact search query","reason":"why"},{"tool":"respond","input":"","reason":"synthesize all"}]}

RULES:
- Use multiple tools when needed to fully answer the question
- search_web for anything needing current/real-world data
- deep_think for complex reasoning or second opinions
- generate_code for any programming tasks
- Always end with respond'
        }
        mut plan_msgs := [plan_sys]
        plan_msgs << history

        plan_text := call_grok(plan_msgs) or {
                push_step(job_id, AgentStep{
                        step_type: 'thinking'
                        content:   'Planning failed, attempting direct response...'
                        model:     'grok-4-0709'
                        timestamp: now_ms()
                })
                direct := call_grok(history) or {
                        error_job(job_id, 'All Grok calls failed: ${err}')
                        return
                }
                complete_job(job_id, conv_id, user_message, direct, 'grok-4-0709')
                return
        }

        tools := parse_plan(plan_text)
        push_step(job_id, AgentStep{
                step_type: 'thinking'
                content:   'Plan ready — ${tools.len} step(s) to execute'
                model:     'grok-4-0709'
                timestamp: now_ms()
        })

        // PHASE 2 — Execute tools
        mut results := []string{}

        for t in tools {
                match t.tool {
                        'search_web' {
                                push_step(job_id, AgentStep{
                                        step_type: 'searching'
                                        content:   'Searching Exa AI (100 results): "${clamp(t.input, 120)}"'
                                        model:     'exa-neural'
                                        timestamp: now_ms()
                                })
                                exa_res := call_exa(t.input) or {
                                        push_step(job_id, AgentStep{
                                                step_type: 'tool_result'
                                                content:   'Exa search failed: ${clamp(err.msg(), 200)}'
                                                model:     'exa-neural'
                                                timestamp: now_ms()
                                        })
                                        continue
                                }
                                mut summary := 'WEB SEARCH "${t.input}" — ${exa_res.len} results found:\n\n'
                                for i, r in exa_res {
                                        if i >= 12 {
                                                summary += '\n... and ${exa_res.len - 12} more results available\n'
                                                break
                                        }
                                        excerpt := clamp(r.text, 600)
                                        summary += '[${i + 1}] **${r.title}**\n${r.url}\n${excerpt}\n\n'
                                }
                                results << summary
                                push_step(job_id, AgentStep{
                                        step_type: 'tool_result'
                                        content:   'Retrieved ${exa_res.len} Exa results for "${clamp(t.input, 80)}"'
                                        model:     'exa-neural'
                                        timestamp: now_ms()
                                })
                        }
                        'deep_think' {
                                push_step(job_id, AgentStep{
                                        step_type: 'deep_thinking'
                                        content:   'GLM-5 deep reasoning: ${clamp(t.input, 120)}...'
                                        model:     'glm-5'
                                        timestamp: now_ms()
                                })
                                think_msgs := [
                                        AiMsg{
                                                role:    'system'
                                                content: 'You are GLM-5, an advanced deep reasoning model. Think step-by-step. Be thorough, precise, and comprehensive. Show your full reasoning chain.'
                                        },
                                        AiMsg{ role: 'user', content: t.input },
                                ]
                                thinking := call_glm(think_msgs) or {
                                        push_step(job_id, AgentStep{
                                                step_type: 'tool_result'
                                                content:   'GLM-5 call failed: ${clamp(err.msg(), 200)}'
                                                model:     'glm-5'
                                                timestamp: now_ms()
                                        })
                                        continue
                                }
                                results << 'DEEP ANALYSIS (GLM-5):\n${thinking}'
                                push_step(job_id, AgentStep{
                                        step_type: 'tool_result'
                                        content:   'GLM-5 analysis complete — ${thinking.len} chars'
                                        model:     'glm-5'
                                        timestamp: now_ms()
                                })
                        }
                        'generate_code' {
                                push_step(job_id, AgentStep{
                                        step_type: 'coding'
                                        content:   'Generating code: ${clamp(t.input, 120)}...'
                                        model:     'grok-4-0709'
                                        timestamp: now_ms()
                                })
                                code_msgs := [
                                        AiMsg{
                                                role:    'system'
                                                content: 'Generate complete, production-ready code.
Requirements:
- Full implementation, zero placeholders
- Proper error handling
- Inline comments
- For system deps: use Nix shell shebang (#!/usr/bin/env nix-shell) with #!nix-shell -i <interpreter> -p <packages>
- Include usage examples
Output clean, immediately runnable code.'
                                        },
                                        AiMsg{ role: 'user', content: t.input },
                                ]
                                code := call_grok(code_msgs) or {
                                        push_step(job_id, AgentStep{
                                                step_type: 'tool_result'
                                                content:   'Code generation failed: ${clamp(err.msg(), 200)}'
                                                model:     'grok-4-0709'
                                                timestamp: now_ms()
                                        })
                                        continue
                                }
                                results << 'GENERATED CODE:\n${code}'
                                push_step(job_id, AgentStep{
                                        step_type: 'tool_result'
                                        content:   'Code generated — ${code.len} chars'
                                        model:     'grok-4-0709'
                                        timestamp: now_ms()
                                })
                        }
                        'respond' {}
                        else {}
                }
        }

        // PHASE 3 — Synthesize final response
        push_step(job_id, AgentStep{
                step_type: 'thinking'
                content:   'Synthesizing comprehensive response with Grok-4...'
                model:     'grok-4-0709'
                timestamp: now_ms()
        })

        mut synth_msgs := [
                AiMsg{
                        role:    'system'
                        content: 'You are NEXUS, an elite AI assistant powered by Grok-4 (fast intelligence) and GLM-5 (deep reasoning).
Synthesize all gathered information into a comprehensive, precise final response.
- Use markdown formatting where appropriate
- Be thorough and cite specific sources when relevant
- For code: provide complete, runnable implementations with Nix support
- Maintain the highest quality standards'
                },
        ]
        synth_msgs << history

        if results.len > 0 {
                synth_msgs << AiMsg{
                        role:    'assistant'
                        content: 'I gathered the following information:\n\n${results.join('\n\n---\n\n')}'
                }
                synth_msgs << AiMsg{
                        role:    'user'
                        content: 'Based on all gathered information, provide your comprehensive final response.'
                }
        }

        final_resp := call_grok(synth_msgs) or {
                push_step(job_id, AgentStep{
                        step_type: 'thinking'
                        content:   'Grok-4 synthesis failed, falling back to GLM-5...'
                        model:     'glm-5'
                        timestamp: now_ms()
                })
                glm_resp := call_glm(synth_msgs) or {
                        error_job(job_id, 'All synthesis models failed: ${err}')
                        return
                }
                push_step(job_id, AgentStep{
                        step_type: 'final'
                        content:   glm_resp
                        model:     'glm-5'
                        timestamp: now_ms()
                })
                complete_job(job_id, conv_id, user_message, glm_resp, 'glm-5')
                return
        }

        push_step(job_id, AgentStep{
                step_type: 'final'
                content:   final_resp
                model:     'grok-4-0709'
                timestamp: now_ms()
        })
        complete_job(job_id, conv_id, user_message, final_resp, 'grok-4-0709')
}

// ─────────────────────────────────────────────────────────────
// HTTP ROUTES
// ─────────────────────────────────────────────────────────────

@['/health'; get]
pub fn (mut app App) health() vweb.Result {
        return app.cors_ok('{"status":"ok","engine":"NEXUS-V","models":["grok-4-0709","glm-5","exa-neural"]}')
}

@['/api/conversations'; options]
pub fn (mut app App) options_convs() vweb.Result {
        return app.cors_ok('')
}

@['/api/chat'; options]
pub fn (mut app App) options_chat() vweb.Result {
        return app.cors_ok('')
}

@['/api/conversations'; get]
pub fn (mut app App) list_conversations() vweb.Result {
        g_mu.@lock()
        mut list := []Conversation{}
        for _, c in g_convs {
                list << c
        }
        g_mu.unlock()
        for i in 0 .. list.len {
                for j in i + 1 .. list.len {
                        if list[i].updated_at < list[j].updated_at {
                                tmp := list[i]
                                list[i] = list[j]
                                list[j] = tmp
                        }
                }
        }
        return app.cors_ok(json.encode(list))
}

@['/api/conversations'; post]
pub fn (mut app App) create_conversation() vweb.Result {
        req := json.decode(CreateConvReq, app.req.data) or {
                return app.cors_ok(json.encode(ErrResp{ error: 'Invalid JSON body' }))
        }
        title := if req.title.trim_space() == '' { 'New Chat' } else { req.title }
        c := Conversation{
                id:         new_id()
                title:      title
                messages:   []
                created_at: now_ms()
                updated_at: now_ms()
        }
        g_mu.@lock()
        g_convs[c.id] = c
        g_mu.unlock()
        return app.cors_ok(json.encode(c))
}

@['/api/conversations/:id'; options]
pub fn (mut app App) options_conv_id(id string) vweb.Result {
        return app.cors_ok('')
}

@['/api/conversations/:id'; get]
pub fn (mut app App) get_conversation(id string) vweb.Result {
        g_mu.@lock()
        c := g_convs[id] or {
                g_mu.unlock()
                return app.cors_ok(json.encode(ErrResp{ error: 'Conversation not found' }))
        }
        g_mu.unlock()
        return app.cors_ok(json.encode(c))
}

@['/api/conversations/:id'; delete]
pub fn (mut app App) delete_conversation(id string) vweb.Result {
        g_mu.@lock()
        g_convs.delete(id)
        g_mu.unlock()
        return app.cors_ok('{"ok":true}')
}

@['/api/chat'; post]
pub fn (mut app App) chat() vweb.Result {
        req := json.decode(ChatReq, app.req.data) or {
                return app.cors_ok(json.encode(ErrResp{ error: 'Invalid JSON body' }))
        }
        if req.conv_id.trim_space() == '' {
                return app.cors_ok(json.encode(ErrResp{ error: 'conv_id is required' }))
        }
        if req.message.trim_space() == '' {
                return app.cors_ok(json.encode(ErrResp{ error: 'message is required' }))
        }
        g_mu.@lock()
        if req.conv_id !in g_convs {
                g_mu.unlock()
                return app.cors_ok(json.encode(ErrResp{ error: 'Conversation not found' }))
        }
        job_id := new_id()
        g_jobs[job_id] = Job{
                id:         job_id
                conv_id:    req.conv_id
                status:     'running'
                steps:      []
                created_at: now_ms()
                updated_at: now_ms()
        }
        g_mu.unlock()
        spawn run_agent(job_id, req.conv_id, req.message)
        return app.cors_ok('{"job_id":"${job_id}"}')
}

@['/api/jobs/:id'; options]
pub fn (mut app App) options_jobs(id string) vweb.Result {
        return app.cors_ok('')
}

@['/api/jobs/:id'; get]
pub fn (mut app App) get_job(id string) vweb.Result {
        g_mu.@lock()
        j := g_jobs[id] or {
                g_mu.unlock()
                return app.cors_ok(json.encode(ErrResp{ error: 'Job not found' }))
        }
        g_mu.unlock()
        return app.cors_ok(json.encode(j))
}

@['/api/jobs/:id'; delete]
pub fn (mut app App) delete_job(id string) vweb.Result {
        g_mu.@lock()
        g_jobs.delete(id)
        g_mu.unlock()
        return app.cors_ok('{"ok":true}')
}

// ─────────────────────────────────────────────────────────────
// MAIN
// ─────────────────────────────────────────────────────────────

fn main() {
        g_convs = map[string]Conversation{}
        g_jobs = map[string]Job{}
        eprintln('═══════════════════════════════════════════════')
        eprintln('  NEXUS AI Backend  —  V lang')
        eprintln('  Models : Grok-4-0709  +  GLM-5  +  Exa·100')
        eprintln('  Port   : 5000')
        eprintln('═══════════════════════════════════════════════')
        app := App{}
        vweb.run(app, 5000)
}

