A fájl `__global` változókat használ, ezért a fordításhoz a V-ben engedélyezni kell a globális változókat (pl. `-enable-globals`), és a web szervert `vweb.run(&App{}, port)` formában indítja.[1][2]

```v
module main

import vweb
import net.http
import json
import os
import time
import rand

struct ChatMessage {
pub mut:
	id        string
	role      string
	content   string
	model_tag string   @[json: 'model']
	files     []string
	timestamp i64
}

struct Conversation {
pub mut:
	id         string
	title      string
	messages   []ChatMessage
	created_at i64
	updated_at i64
}

struct AgentStep {
pub mut:
	step_type string
	content   string
	model     string
	timestamp i64
}

struct Job {
pub mut:
	id             string
	conv_id        string
	status         string
	steps          []AgentStep
	final_response string
	error_msg      string
	created_at     i64
	updated_at     i64
}

__global (
	shared g_convs map[string]Conversation
	shared g_jobs  map[string]Job
)

fn init() {
	lock g_convs {
		g_convs = map[string]Conversation{}
	}
	lock g_jobs {
		g_jobs = map[string]Job{}
	}
}

struct CreateConvReq {
pub:
	title string
}

struct ChatReq {
pub:
	conv_id string
	message string
	files   []string
}

struct ErrResp {
pub:
	error string
}

struct JobIdResp {
pub:
	job_id string
}

struct OkResp {
pub:
	ok bool
}

struct HealthResp {
pub:
	status string
	engine string
	models []string
}

struct AiMsg {
pub:
	role    string
	content string
}

struct AiRequest {
pub:
	model      string
	messages   []AiMsg
	max_tokens int
}

struct AiChoice {
pub:
	message AiMsg
}

struct AiResponse {
pub:
	choices []AiChoice
}

struct ExaResultItem {
pub:
	title string
	url   string
	text  string
}

struct ExaResponse {
pub:
	results []ExaResultItem
}

struct ExaReq {
pub:
	query          string
	num_results    int    @[json: 'numResults']
	use_autoprompt bool   @[json: 'useAutoprompt']
	search_type    string @[json: 'type']
	text           bool
}

struct ToolStep {
pub:
	tool   string
	input  string
	reason string
}

struct AgentPlan {
pub:
	steps []ToolStep
}

pub struct App {
	vweb.Context
}

fn new_id() string {
	return rand.uuid_v4()
}

fn now_ms() i64 {
	return time.now().unix_time_milli()
}

fn clamp_chars(s string, max_chars int) string {
	if max_chars <= 0 {
		return ''
	}
	r := s.runes()
	if r.len <= max_chars {
		return s
	}
	return string(r[..max_chars])
}

fn (mut app App) set_cors() {
	app.add_header('Access-Control-Allow-Origin', '*')
	app.add_header('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS, PUT')
	app.add_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
	app.add_header('Content-Type', 'application/json')
}

fn (mut app App) send_json(status int, body string) vweb.Result {
	app.set_cors()
	app.set_status(status, '')
	return app.ok(body)
}

fn (mut app App) send_obj[T](status int, obj T) vweb.Result {
	return app.send_json(status, json.encode(obj))
}

fn (mut app App) unauthorized() vweb.Result {
	return app.send_obj(401, ErrResp{ error: 'Unauthorized' })
}

fn (mut app App) bad_request(msg string) vweb.Result {
	return app.send_obj(400, ErrResp{ error: msg })
}

fn (mut app App) not_found(msg string) vweb.Result {
	return app.send_obj(404, ErrResp{ error: msg })
}

fn (mut app App) too_large() vweb.Result {
	return app.send_obj(413, ErrResp{ error: 'Request body too large' })
}

fn (mut app App) check_auth() bool {
	token := os.getenv('API_TOKEN')
	if token == '' {
		return true
	}
	auth := app.req.header.get(.authorization) or { '' }
	return auth == 'Bearer ${token}'
}

fn call_grok(messages []AiMsg) !string {
	api_key := os.getenv('XAI_API_KEY')
	if api_key == '' {
		return error('XAI_API_KEY not set')
	}
	req_body := AiRequest{
		model:      'grok-4-0709'
		messages:   messages
		max_tokens: 32768
	}
	mut header := http.new_header_from_map({
		http.CommonHeader.content_type:  'application/json'
		http.CommonHeader.authorization: 'Bearer ${api_key}'
	})
	resp := http.fetch(http.FetchConfig{
		url:    ''
		method: .post
		header: header
		data:   json.encode(req_body)
	}) or { return error('Grok fetch failed: ${err}') }
	if resp.status_code != 200 {
		return error('Grok HTTP ${resp.status_code}: ${clamp_chars(resp.body, 300)}')
	}
	parsed := json.decode(AiResponse, resp.body) or {
		return error('Grok decode failed: ${err}')
	}
	if parsed.choices.len == 0 {
		return error('Grok: no choices in response')
	}
	return parsed.choices[0].message.content
}

fn call_glm(messages []AiMsg) !string {
	api_key := os.getenv('GLM_API_KEY')
	if api_key == '' {
		return error('GLM_API_KEY not set')
	}
	req_body := AiRequest{
		model:      'glm-5'
		messages:   messages
		max_tokens: 32768
	}
	mut header := http.new_header_from_map({
		http.CommonHeader.content_type:  'application/json'
		http.CommonHeader.authorization: 'Bearer ${api_key}'
	})
	resp := http.fetch(http.FetchConfig{
		url:    ''
		method: .post
		header: header
		data:   json.encode(req_body)
	}) or { return error('GLM fetch failed: ${err}') }
	if resp.status_code != 200 {
		return error('GLM HTTP ${resp.status_code}: ${clamp_chars(resp.body, 300)}')
	}
	parsed := json.decode(AiResponse, resp.body) or {
		return error('GLM decode failed: ${err}')
	}
	if parsed.choices.len == 0 {
		return error('GLM: no choices in response')
	}
	return parsed.choices[0].message.content
}

fn call_exa(query string) ![]ExaResultItem {
	api_key := os.getenv('EXA_API_KEY')
	if api_key == '' {
		return error('EXA_API_KEY not set')
	}
	req_body := ExaReq{
		query:          query
		num_results:    100
		use_autoprompt: true
		search_type:    'neural'
		text:           true
	}
	mut header := http.new_header_from_map({
		http.CommonHeader.content_type: 'application/json'
	})
	header.add_custom('x-api-key', api_key) or { return error('Failed to add Exa header: ${err}') }
	resp := http.fetch(http.FetchConfig{
		url:    ''
		method: .post
		header: header
		data:   json.encode(req_body)
	}) or { return error('Exa fetch failed: ${err}') }
	if resp.status_code != 200 {
		return error('Exa HTTP ${resp.status_code}: ${clamp_chars(resp.body, 300)}')
	}
	parsed := json.decode(ExaResponse, resp.body) or {
		return error('Exa decode failed: ${err}')
	}
	return parsed.results
}

fn parse_plan(text string) []ToolStep {
	mut json_str := ''
	if text.contains('```json') {
		s_idx := text.index('```json') or { return direct_respond(text) }
		rest := text[s_idx + 7..]
		e_idx := rest.index('```') or { return direct_respond(text) }
		json_str = rest[..e_idx].trim_space()
	} else if text.contains('{"steps"') {
		s_idx := text.index('{"steps"') or { return direct_respond(text) }
		sub := text[s_idx..]
		e_idx := sub.index_last('}') or { return direct_respond(text) }
		json_str = sub[..e_idx + 1]
	} else {
		return direct_respond(text)
	}
	plan := json.decode(AgentPlan, json_str) or { return direct_respond(text) }
	if plan.steps.len == 0 {
		return direct_respond(text)
	}
	return plan.steps
}

fn direct_respond(text string) []ToolStep {
	return [ToolStep{ tool: 'respond', input: text, reason: 'direct response' }]
}

fn push_step(job_id string, step AgentStep) {
	lock g_jobs {
		if job_id in g_jobs {
			mut j := g_jobs[job_id]
			j.steps << step
			j.updated_at = now_ms()
			g_jobs[job_id] = j
		}
	}
}

fn set_job_status(job_id string, status string, final_response string, error_msg string) {
	lock g_jobs {
		if job_id in g_jobs {
			mut j := g_jobs[job_id]
			j.status = status
			j.final_response = final_response
			j.error_msg = error_msg
			j.updated_at = now_ms()
			g_jobs[job_id] = j
		}
	}
}

fn append_assistant(conv_id string, response string, model_name string) {
	lock g_convs {
		if conv_id in g_convs {
			mut c := g_convs[conv_id]
			c.messages << ChatMessage{
				id:        new_id()
				role:      'assistant'
				content:   response
				model_tag: model_name
				files:     []string{}
				timestamp: now_ms()
			}
			c.updated_at = now_ms()
			g_convs[conv_id] = c
		}
	}
}

fn run_agent(job_id string, conv_id string, user_message string) {
	push_step(job_id, AgentStep{
		step_type: 'thinking'
		content:   'Analyzing request and planning approach with Grok-4-0709...'
		model:     'grok-4-0709'
		timestamp: now_ms()
	})
	mut history := []AiMsg{}
	lock g_convs {
		if conv_id !in g_convs {
			set_job_status(job_id, 'error', '', 'Conversation not found: ${conv_id}')
			return
		}
		c := g_convs[conv_id]
		for m in c.messages {
			if m.role == 'user' || m.role == 'assistant' || m.role == 'system' {
				history << AiMsg{ role: m.role, content: m.content }
			}
		}
	}
	history << AiMsg{ role: 'user', content: user_message }
	plan_sys := AiMsg{
		role: 'system'
		content: 'You are NEXUS, an autonomous AI orchestrator powered by Grok-4 and GLM-5.
Given the user message, output a JSON plan of tools to execute.

TOOLS AVAILABLE:
- search_web    : search internet with Exa (100 results, neural ranking). Use for current info, facts, news, research.
- deep_think    : invoke GLM-5 deep reasoning. Use for complex logic, math, analysis, architecture decisions.
- generate_code : write complete production code supporting any language via Nix. Use for programming tasks.
- respond       : synthesize and return final answer. ALWAYS include as last step.

OUTPUT FORMAT (valid JSON only, no extra text):
{"steps":[{"tool":"search_web","input":"exact search query","reason":"why"},{"tool":"respond","input":"","reason":"synthesize all"}]}

RULES:
- Use multiple tools when needed to fully answer the question
- search_web for anything needing current/real-world data
- deep_think for complex reasoning or second opinions
- generate_code for any programming tasks
- Always end with respond'
	}
	mut plan_msgs := []AiMsg{}
	plan_msgs << plan_sys
	for m in history {
		plan_msgs << m
	}
	plan_text := call_grok(plan_msgs) or {
		push_step(job_id, AgentStep{
			step_type: 'thinking'
			content:   'Planning failed, attempting direct response...'
			model:     'grok-4-0709'
			timestamp: now_ms()
		})
		direct := call_grok(history) or {
			set_job_status(job_id, 'error', '', 'All Grok calls failed: ${err}')
			return
		}
		push_step(job_id, AgentStep{
			step_type: 'final'
			content:   direct
			model:     'grok-4-0709'
			timestamp: now_ms()
		})
		set_job_status(job_id, 'done', direct, '')
		append_assistant(conv_id, direct, 'grok-4-0709')
		return
	}
	tools := parse_plan(plan_text)
	if tools.len == 1 && tools.tool == 'respond' && tools.input.trim_space() != '' {
		push_step(job_id, AgentStep{
			step_type: 'final'
			content:   tools.input
			model:     'grok-4-0709'
			timestamp: now_ms()
		})
		set_job_status(job_id, 'done', tools.input, '')
		append_assistant(conv_id, tools.input, 'grok-4-0709')
		return
	}
	push_step(job_id, AgentStep{
		step_type: 'thinking'
		content:   'Plan ready — ${tools.len} step(s) to execute'
		model:     'grok-4-0709'
		timestamp: now_ms()
	})
	mut results := []string{}
	for t in tools {
		match t.tool {
			'search_web' {
				query := t.input.trim_space()
				if query == '' {
					continue
				}
				push_step(job_id, AgentStep{
					step_type: 'searching'
					content:   'Searching Exa AI (100 results): "${clamp_chars(query, 120)}"'
					model:     'exa-neural'
					timestamp: now_ms()
				})
				exa_res := call_exa(query) or {
					push_step(job_id, AgentStep{
						step_type: 'tool_result'
						content:   'Exa search failed: ${clamp_chars(err.msg(), 200)}'
						model:     'exa-neural'
						timestamp: now_ms()
					})
					continue
				}
				mut summary := 'WEB SEARCH "${query}" — ${exa_res.len} results found:\n\n'
				for i, r in exa_res {
					if i >= 12 {
						summary += '\n... and ${exa_res.len - 12} more results available\n'
						break
					}
					excerpt := clamp_chars(r.text, 600)
					summary += '[${i + 1}] ${r.title}\n${r.url}\n${excerpt}\n\n'
				}
				results << summary
				push_step(job_id, AgentStep{
					step_type: 'tool_result'
					content:   'Retrieved ${exa_res.len} Exa results for "${clamp_chars(query, 80)}"'
					model:     'exa-neural'
					timestamp: now_ms()
				})
			}
			'deep_think' {
				inp := t.input.trim_space()
				if inp == '' {
					continue
				}
				push_step(job_id, AgentStep{
					step_type: 'deep_thinking'
					content:   'GLM-5 deep reasoning: ${clamp_chars(inp, 120)}...'
					model:     'glm-5'
					timestamp: now_ms()
				})
				think_msgs := [
					AiMsg{
						role:    'system'
						content: 'You are GLM-5, an advanced deep reasoning model. Provide a thorough, precise answer.'
					},
					AiMsg{ role: 'user', content: inp },
				]
				thinking := call_glm(think_msgs) or {
					push_step(job_id, AgentStep{
						step_type: 'tool_result'
						content:   'GLM-5 call failed: ${clamp_chars(err.msg(), 200)}'
						model:     'glm-5'
						timestamp: now_ms()
					})
					continue
				}
				results << 'DEEP ANALYSIS (GLM-5):\n${thinking}'
				push_step(job_id, AgentStep{
					step_type: 'tool_result'
					content:   'GLM-5 analysis complete — ${thinking.len} chars'
					model:     'glm-5'
					timestamp: now_ms()
				})
			}
			'generate_code' {
				inp := t.input.trim_space()
				if inp == '' {
					continue
				}
				push_step(job_id, AgentStep{
					step_type: 'coding'
					content:   'Generating code: ${clamp_chars(inp, 120)}...'
					model:     'grok-4-0709'
					timestamp: now_ms()
				})
				code_msgs := [
					AiMsg{
						role: 'system'
						content: 'Generate complete, production-ready code.
Requirements:
- Full implementation, zero placeholders
- Proper error handling
- Include usage examples
Output clean, immediately runnable code.'
					},
					AiMsg{ role: 'user', content: inp },
				]
				code := call_grok(code_msgs) or {
					push_step(job_id, AgentStep{
						step_type: 'tool_result'
						content:   'Code generation failed: ${clamp_chars(err.msg(), 200)}'
						model:     'grok-4-0709'
						timestamp: now_ms()
					})
					continue
				}
				results << 'GENERATED CODE:\n${code}'
				push_step(job_id, AgentStep{
					step_type: 'tool_result'
					content:   'Code generated — ${code.len} chars'
					model:     'grok-4-0709'
					timestamp: now_ms()
				})
			}
			'respond' {
				continue
			}
			else {
				continue
			}
		}
	}
	push_step(job_id, AgentStep{
		step_type: 'thinking'
		content:   'Synthesizing comprehensive response with Grok-4...'
		model:     'grok-4-0709'
		timestamp: now_ms()
	})
	mut synth_msgs := []AiMsg{}
	synth_msgs << AiMsg{
		role: 'system'
		content: 'You are NEXUS, an elite AI assistant powered by Grok-4 and GLM-5.
Synthesize all gathered information into a comprehensive, precise final response.
Use markdown formatting where appropriate.
Cite specific sources when relevant.'
	}
	for m in history {
		synth_msgs << m
	}
	if results.len > 0 {
		synth_msgs << AiMsg{
			role:    'assistant'
			content: 'I gathered the following information:\n\n${results.join('\n\n---\n\n')}'
		}
		synth_msgs << AiMsg{
			role:    'user'
			content: 'Based on all gathered information, provide your comprehensive final response.'
		}
	}
	final_resp := call_grok(synth_msgs) or {
		push_step(job_id, AgentStep{
			step_type: 'thinking'
			content:   'Grok-4 synthesis failed, falling back to GLM-5...'
			model:     'glm-5'
			timestamp: now_ms()
		})
		glm_resp := call_glm(synth_msgs) or {
			set_job_status(job_id, 'error', '', 'All synthesis models failed: ${err}')
			return
		}
		push_step(job_id, AgentStep{
			step_type: 'final'
			content:   glm_resp
			model:     'glm-5'
			timestamp: now_ms()
		})
		set_job_status(job_id, 'done', glm_resp, '')
		append_assistant(conv_id, glm_resp, 'glm-5')
		return
	}
	push_step(job_id, AgentStep{
		step_type: 'final'
		content:   final_resp
		model:     'grok-4-0709'
		timestamp: now_ms()
	})
	set_job_status(job_id, 'done', final_resp, '')
	append_assistant(conv_id, final_resp, 'grok-4-0709')
}

