@['/api/conversations'; get]
pub fn (mut app App) list_conversations() vweb.Result {
	if !app.check_auth() {
		return app.unauthorized()
	}
	mut list := []Conversation{}
	lock g_convs {
		for _, c in g_convs {
			list << c
		}
	}
	for i in 0 .. list.len {
		for j in i + 1 .. list.len {
			if list[i].updated_at < list[j].updated_at {
				tmp := list[i]
				list[i] = list[j]
				list[j] = tmp
			}
		}
	}
	return app.send_json(200, json.encode(list))
}

@['/api/conversations'; post]
pub fn (mut app App) create_conversation() vweb.Result {
	if !app.check_auth() {
		return app.unauthorized()
	}
	if app.req.data.len > 1024 * 1024 {
		return app.too_large()
	}
	req := json.decode(CreateConvReq, app.req.data) or {
		return app.bad_request('Invalid JSON body')
	}
	title := if req.title.trim_space() == '' { 'New Chat' } else { req.title.trim_space() }
	c := Conversation{
		id:         new_id()
		title:      title
		messages:   []ChatMessage{}
		created_at: now_ms()
		updated_at: now_ms()
	}
	lock g_convs {
		g_convs[c.id] = c
	}
	return app.send_json(201, json.encode(c))
}

