@['/api/chat'; post]
pub fn (mut app App) chat() vweb.Result {
	if !app.check_auth() {
		return app.unauthorized()
	}
	if app.req.data.len > 1024 * 1024 {
		return app.too_large()
	}
	req := json.decode(ChatReq, app.req.data) or {
		return app.bad_request('Invalid JSON body')
	}
	conv_id := req.conv_id.trim_space()
	msg := req.message.trim_space()
	if conv_id == '' {
		return app.bad_request('conv_id is required')
	}
	if msg == '' {
		return app.bad_request('message is required')
	}
	mut exists := false
	lock g_convs {
		if conv_id in g_convs {
			exists = true
			mut c := g_convs[conv_id]
			c.messages << ChatMessage{
				id:        new_id()
				role:      'user'
				content:   msg
				model_tag: ''
				files:     req.files
				timestamp: now_ms()
			}
			c.updated_at = now_ms()
			if c.title == 'New Chat' || c.title.trim_space() == '' {
				words := msg.split(' ')
				c.title = if words.len > 6 {
					words[..6].join(' ') + '...'
				} else {
					msg
				}
			}
			g_convs[conv_id] = c
		}
	}
	if !exists {
		return app.not_found('Conversation not found')
	}
	job_id := new_id()
	lock g_jobs {
		g_jobs[job_id] = Job{
			id:         job_id
			conv_id:    conv_id
			status:     'running'
			steps:      []AgentStep{}
			created_at: now_ms()
			updated_at: now_ms()
		}
	}
	spawn run_agent(job_id, conv_id, msg)
	return app.send_obj(202, JobIdResp{ job_id: job_id })
}

